    private static void Mark(HashSet<string> busy, string type, long id, int day, int slot, int parity) => busy.Add(type + id + ":" + day + ":" + slot + ":" + parity);
    private static long Insert(SqliteConnection c, SqliteTransaction t, string table, params (string Name, object? Value)[] values) { using var cmd = c.CreateCommand(); cmd.Transaction = t; cmd.CommandText = "INSERT INTO " + table + " (" + string.Join(',', values.Select(x => x.Name)) + ") VALUES (" + string.Join(',', values.Select((_, i) => "@p" + i)) + "); SELECT last_insert_rowid();"; for (int i = 0; i < values.Length; i++) cmd.Parameters.AddWithValue("@p" + i, values[i].Value ?? DBNull.Value); return (long)(cmd.ExecuteScalar() ?? 0L); }
    private static void Execute(SqliteConnection c, SqliteTransaction t, string sql, params object?[] values) { using var cmd = c.CreateCommand(); cmd.Transaction = t; cmd.CommandText = sql; for (int i = 0; i < values.Length; i++) cmd.Parameters.AddWithValue("@p" + i, values[i] ?? DBNull.Value); cmd.ExecuteNonQuery(); }
